import ast,asyncio,json,pathlib,shutil,re,copy
from playwright.async_api import async_playwright
R=pathlib.Path(__file__).resolve().parent.parent;OUT=R/'out';V=R/'verification-3.0';OUT.mkdir(exist_ok=True);V.mkdir(exist_ok=True)
t=ast.parse((R/'tests/ui_test.py').read_text());fixture=eval(compile(ast.Expression(next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='fixture' for t in n.targets))),'fixture','eval'),{'__builtins__':{}})
skills=[dict(id=id,name=name,description=desc,source='Встроено · текстовые инструкции') for id,name,desc in re.findall(r'new\("([^"]+)","([^"]+)","([^"]+)"', (R/'src/SkillPack.cs').read_text().split('public static void Validate')[0])]
fixture['skills']=skills;fixture['settings'].update(skillsEnabled=True,skillsAuto=True,skillIds=[s['id'] for s in skills]);checks=[]
async def run():
 async with async_playwright() as p:
  b=await p.chromium.launch(executable_path=shutil.which('chromium'),headless=True,args=['--no-sandbox']);page=await b.new_page(viewport={'width':1440,'height':940});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
  await page.add_init_script('window.__sent=[];window.chrome=window.chrome||{};window.chrome.webview={postMessage(x){window.__sent.push(JSON.parse(x))},addEventListener(){}}')
  await page.goto((R/'src/ui.html').as_uri());await page.evaluate('(d)=>receive({type:"state",data:d})',fixture)
  async def check(yes,name):assert yes,name;checks.append(name)
  await page.locator('#skills-btn').click();await check(await page.locator('#skills-modal').is_visible(),'skills reachable in agents panel');await check(await page.locator('.skill-option').count()==26,'26 built-in skills displayed');bb=await page.locator('#skills-save').bounding_box();await check(bb is not None and bb['y']+bb['height']<=940,'desktop apply visible without scrolling');await check(await page.locator('#skills-enabled').is_checked() and await page.locator('#skills-auto').is_checked(),'enabled and automatic defaults visible');await check(await page.locator('.skill-option input:checked').count()==26,'all skills eligible by default')
  await page.locator('.skill-option input[value="tests"]').uncheck();await page.locator('#skills-auto').uncheck();await page.locator('#skills-save').click();await check(await page.evaluate('__sent.at(-1).action==="skills"'),'skill apply dispatch');await check(await page.evaluate('__sent.at(-1).data.ids.length===25&&!__sent.at(-1).data.ids.includes("tests")&&!__sent.at(-1).data.automatic'),'manual subset saved without unselected skill')
  await page.evaluate('receive({type:"skillsSaved"})');await check(await page.locator('#skills-modal').is_hidden(),'done closes modal');await page.locator('#agent-select').select_option('code-team');await check(await page.evaluate('__sent.at(-1).action==="selectAgent"&&__sent.at(-1).data.id==="code-team"'),'code team selector dispatch');await check(await page.locator('#agent-select option[value="team"]').count()==1,'legacy design team retained')
  await page.locator('#prompt').fill('/team напиши код Python');await page.locator('#send-btn').click();await check(await page.evaluate('__sent.at(-1).action==="send"&&__sent.at(-1).data.text.startsWith("/team")'),'slash command sent intact to host')
  await page.evaluate('receive({type:"busy",data:true})');await check(await page.locator('#skills-btn').is_disabled() and await page.locator('#skills-save').is_disabled(),'busy prevents settings changes');await page.evaluate('receive({type:"busy",data:false})')
  malicious=copy.deepcopy(fixture);malicious['skills'][0]['name']='<img src=x onerror="window.pwned=1">';await page.evaluate('(d)=>receive({type:"state",data:d})',malicious);await page.evaluate('skillsModal()');await check(await page.evaluate('window.pwned===undefined') and await page.locator('#skills-list img').count()==0,'skill metadata escaped, not rendered HTML')
  await page.evaluate('(d)=>receive({type:"state",data:d})',fixture);await page.evaluate('skillsModal()');await check(await page.evaluate('document.documentElement.scrollWidth===innerWidth'),'desktop no horizontal overflow');await check('не объединение весов' in await page.locator('.skill-team').inner_text(),'sequential model limitation explicit');await check('не антивирусная' in await page.locator('#skills-modal').inner_text(),'audit scope explicit')
  source=(R/'src/ui.html').read_text();payload=json.dumps(fixture,ensure_ascii=False).replace('</','<\\/');(OUT/'skills-3.0.html').write_text(source.replace('</body>',f'<script>setTimeout(()=>{{receive({{type:"state",data:{payload}}});skillsModal()}},150)</script></body>'))
  await page.set_viewport_size({'width':390,'height':844});await check(await page.evaluate('document.documentElement.scrollWidth===innerWidth'),'mobile no horizontal overflow');bb=await page.locator('#skills-save').bounding_box();await check(bb is not None and bb['y']+bb['height']<=844,'mobile apply visible without scrolling');await page.locator('#skills-save').scroll_into_view_if_needed();await check(await page.locator('#skills-save').is_visible(),'mobile apply reachable');await page.locator('.skill-option').first.scroll_into_view_if_needed();await check(await page.locator('.skill-option').evaluate_all('(nodes)=>nodes.every(n=>n.scrollWidth<=n.clientWidth)'),'mobile skill cards fit');await check(not errors,'no JavaScript errors')
  (V/'skills-ui.json').write_text(json.dumps({'passed':len(checks),'checks':checks,'scope':'HTML mocks, not Windows runtime'},ensure_ascii=False,indent=2));print(len(checks),'skills UI checks passed');await b.close()
asyncio.run(run())
